const $=id=>document.getElementById(id);
const API_BASE=location.protocol==='file:'?'http://localhost:3001':'';
const SESSION_ID=localStorage.getItem('saarthi_session')||(()=>{const id=crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2);localStorage.setItem('saarthi_session',id);return id})();
let state={hasData:false,analytics:null};
const SAMPLE_PROBLEM='I earn ₹55,000 a month. I want to save ₹10,000 every month and buy a ₹45,000 laptop in 3 months. Tell me if this is realistic and what I should change.';
const SAMPLE_DATA=`Date,Description,Category,Amount\n2026-09-01,Salary,Income,55000\n2026-09-02,Rent,Housing,-15000\n2026-09-03,Swiggy,Food,-3200\n2026-09-04,Amazon,Shopping,-6500\n2026-09-05,Uber,Transport,-1800\n2026-09-06,Electricity,Bills,-3000\n2026-09-07,Netflix,Subscriptions,-649\n2026-09-08,Shopping,Shopping,-2500\n2026-09-09,Groceries,Food,-2800`;
async function api(path,opt={}){const headers={...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),'x-saarthi-session':SESSION_ID,...(opt.headers||{})};let r,j;try{r=await fetch(`${API_BASE}${path}`,{...opt,headers});}catch(e){throw new Error(`Backend unavailable. Start Saarthi with npm start and try again. (${e.message})`)}j=await r.json().catch(()=>({}));if(!r.ok){const detail=j?.error?.message||j?.error||`Request failed (${r.status})`;const code=j?.error?.code;throw new Error(code?`${detail} [${code}]`:detail)}return j;}
function money(n){return `₹${Math.round(Number(n)||0).toLocaleString('en-IN')}`}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function setText(id,t){const e=$(id);if(e)e.textContent=t}
function showToast(t){let x=$('toast');if(!x){x=document.createElement('div');x.id='toast';x.style='position:fixed;right:20px;bottom:20px;z-index:99999;background:#29264e;color:white;padding:12px 16px;border-radius:11px;font:600 12px DM Sans;box-shadow:0 15px 40px #0003';document.body.appendChild(x)}x.textContent=t;x.style.display='block';clearTimeout(window.__toast);window.__toast=setTimeout(()=>x.style.display='none',3000)}
function setupAuth(){const auth=$('auth-screen');if(localStorage.getItem('saarthi_signed_in')==='1')auth.style.display='none';const sign=()=>{localStorage.setItem('saarthi_signed_in','1');auth.style.display='none';showToast('Welcome to Saarthi.');};$('login-form')?.addEventListener('submit',e=>{e.preventDefault();sign()});$('demo-login')?.addEventListener('click',sign);$('logout-btn')?.addEventListener('click',()=>{localStorage.removeItem('saarthi_signed_in');location.reload()})}
function showSection(name){document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.section===name));document.querySelectorAll('.section').forEach(x=>x.classList.toggle('active',x.id===name+'-section'));const titles={dashboard:['Financial overview','Your money, understood simply.'],analytics:['Financial intelligence','Saarthi finds patterns in your data.'],transactions:['Your data','The financial information Saarthi is using.'],chat:['Ask Saarthi','Ask a question. Saarthi will reason from your data.'],banks:['Connect bank','Optional demo connection — your own data is the primary source.'],workspace:['My Data','Give Saarthi the context it needs to help you.']};setText('page-title',(titles[name]||titles.dashboard)[0]);setText('page-subtitle',(titles[name]||titles.dashboard)[1]);if(name==='analytics')renderAnalytics(state.analytics);if(name==='transactions')renderTransactions(state.analytics?.transactions||[]);if(name==='workspace')renderContext();closeMobile()}
function closeMobile(){$('sidebar')?.classList.remove('open')}
function setupNav(){document.addEventListener('click',e=>{const n=e.target.closest('[data-go]');if(n){e.preventDefault();showSection(n.dataset.go);return}const b=e.target.closest('.nav-item');if(b){e.preventDefault();showSection(b.dataset.section)}});$('mobile-menu')?.addEventListener('click',()=>$('sidebar')?.classList.toggle('open'))}
function setupWorkspace(){const drop=$('upload-drop'),file=$('data-file');$('choose-file')?.addEventListener('click',e=>{e.stopPropagation();file.click()});drop?.addEventListener('click',e=>{if(e.target.tagName!=='BUTTON')file.click()});['dragenter','dragover'].forEach(x=>drop?.addEventListener(x,e=>{e.preventDefault();drop.classList.add('drag')}));['dragleave','drop'].forEach(x=>drop?.addEventListener(x,e=>{e.preventDefault();drop.classList.remove('drag')}));drop?.addEventListener('drop',e=>{if(e.dataTransfer.files[0]){file.files=e.dataTransfer.files;showToast('File selected: '+e.dataTransfer.files[0].name)}});file?.addEventListener('change',()=>{if(file.files[0])$('upload-status').textContent=`Selected: ${file.files[0].name}`});$('use-sample')?.addEventListener('click',()=>{$('problem-input').value=SAMPLE_PROBLEM;$('data-input').value=SAMPLE_DATA});$('analyze-data')?.addEventListener('click',analyzeUserData);$('reset-data')?.addEventListener('click',resetData);}
async function analyzeUserData(){const problem=$('problem-input').value.trim();const file=$('data-file').files[0];const paste=$('data-input').value.trim();if(!problem&&!file&&!paste){showToast('Tell Saarthi what you want to figure out and add some data.');return}$('upload-status').textContent='Saarthi is understanding your data…';try{let j;if(file){const fd=new FormData();fd.append('file',file);fd.append('problem',problem);j=await api('/api/import',{method:'POST',body:fd})}else{j=await api('/api/import',{method:'POST',body:JSON.stringify({problem,data:paste})})}state={hasData:true,analytics:j.analytics};renderContext(j.context);renderAnalysis(j.analytics);$('upload-status').textContent=`Understood ${j.context.detected} usable transaction rows.`;showToast('Saarthi has understood your financial context.');showSection('workspace')}catch(e){$('upload-status').textContent=e.message;showToast(e.message)}}
function renderContext(c){const box=$('context-summary');if(!box)return;if(!state.hasData&&!c){box.innerHTML='<div class="empty-state"><div>✦</div><strong>Your financial context will appear here.</strong><p>Saarthi will detect columns, amounts, dates, categories, income, expenses and goals automatically.</p></div>';return}c=c||{};box.innerHTML=`<div class="context-stats"><div class="context-stat"><span>Rows understood</span><strong>${c.detected??state.analytics?.transactionCount??0}</strong></div><div class="context-stat"><span>Source</span><strong>${esc(c.filename||c.source||'User data')}</strong></div><div class="context-stat"><span>Income detected</span><strong>${money(c.totalIncome??state.analytics?.totalIncome)}</strong></div><div class="context-stat"><span>Expenses detected</span><strong>${money(c.totalExpenses??state.analytics?.totalExpenses)}</strong></div></div><div class="workspace-panel-note">Detected structure: ${(c.columns||['date','merchant','category','amount']).join(' · ')}</div>`;setText('context-badge','Context ready')}
function renderAnalysis(a){const out=$('analysis-output');if(!out||!a)return;out.classList.remove('hidden');const cats=(a.categories||[]).slice(0,7);const audit=a.audit||{};const confidence=a.transactionCount>=50&&audit.coverage!=='Limited'?'High':a.transactionCount>=10?'Medium':'Low';out.innerHTML=`<article class="panel"><div class="analysis-head"><div><span class="section-kicker">SAARTHI REASONING</span><h3>Here's what your data says.</h3><p class="workspace-panel-note">Saarthi calculated this from your supplied data — and separated findings from items that need human review.</p></div><span class="mini-badge">Confidence: ${confidence}</span></div><div class="analysis-grid"><div class="analysis-stat"><span>INCOME</span><strong>${money(a.totalIncome)}</strong></div><div class="analysis-stat"><span>EXPENSES</span><strong>${money(a.totalExpenses)}</strong></div><div class="analysis-stat"><span>SURPLUS</span><strong>${money(a.netSavings)}</strong></div><div class="analysis-stat"><span>SAVINGS RATE</span><strong>${a.savingsRate}%</strong></div></div><div class="audit-strip"><div><b>🔎 ${audit.reviewCount||0}</b><span>items to review</span></div><div><b>♻ ${audit.duplicates||0}</b><span>possible duplicates</span></div><div><b>⚠ ${audit.anomalies||0}</b><span>unusual expenses</span></div><div><b>↻ ${audit.recurring?.length||0}</b><span>recurring patterns</span></div><div><b>${audit.coverage||'Limited'}</b><span>data coverage</span></div></div><div class="analysis-panels"><div><div class="recommendation"><h4>✦ Saarthi's recommendation</h4><p>${esc(a.recommendation)}</p></div><div class="categories" style="margin-top:16px">${cats.map(x=>`<div class="category-row"><div class="category-name">${esc(x.category)}</div><div class="progress"><div class="progress-fill" style="width:${Math.round(x.amount/Math.max(cats[0]?.amount||1,1)*100)}%"></div></div><div class="category-amount">${money(x.amount)}</div></div>`).join('')}</div></div><div><span class="section-kicker">AUDIT INTELLIGENCE</span><div class="audit-list">${(audit.issues||[]).slice(0,6).map(i=>`<div class="audit-item ${esc(i.severity)}"><div><strong>${esc(i.title)}</strong><p>${esc(i.text)}</p></div><span>${i.confidence||0}%</span></div>`).join('')||'<div class="empty-state compact"><strong>No immediate flags.</strong><p>Saarthi did not find obvious duplicates or anomalies in the supplied rows.</p></div>'}</div></div></div><div class="scenario-box"><span class="section-kicker">WHAT IF?</span><h3 style="margin:5px 0 12px;font:700 15px Manrope">Test a change before making it.</h3><div class="scenario-controls"><label>Category<select id="scenario-category">${cats.map(x=>`<option value="${esc(x.category)}">${esc(x.category)} — ${money(x.amount)}</option>`).join('')}</select></label><label>Reduce by <input id="scenario-reduction" type="range" min="0" max="50" value="10"><output id="scenario-value">10%</output></label></div><div id="scenario-result" class="scenario-result">Move the slider to simulate the effect.</div></div></article>`;const range=$('scenario-reduction');const update=async()=>{const cat=$('scenario-category').value;const reduction=Number(range.value);setText('scenario-value',reduction+'%');try{const r=await api('/api/simulate',{method:'POST',body:JSON.stringify({category:cat,reduction})});$('scenario-result').innerHTML=`Reducing <b>${esc(cat)}</b> by ${reduction}% could free <b>${money(r.savingsPerPeriod)}</b> per period and <b>${money(r.yearlySavings)}</b> over 12 periods. Estimated surplus becomes <b>${money(r.newSurplus)}</b>.`;}catch(e){}};range?.addEventListener('input',update);$('scenario-category')?.addEventListener('change',update);update()}
function renderDashboard(a){if(!a){['balance','income','expenses','savings'].forEach(x=>setText(x,'—'));return}setText('balance','—');setText('income',money(a.totalIncome));setText('expenses',money(a.totalExpenses));setText('savings',money(a.netSavings));setText('savings-rate',`${a.savingsRate}% savings rate`);setText('health-score',a.healthScore);const ring=$('health-ring');if(ring)ring.style.setProperty('--score',`${a.healthScore}%`);setText('health-label',a.healthScore>=75?'Healthy foundation':a.healthScore>=55?'Room to improve':'Needs attention');renderCategories(a.categories,$('dashboard-categories'));renderChart(a.monthly,$('monthly-chart'));renderTransactions(a.transactions?.slice(0,6)||[],$('recent-transactions'));const ins=$('main-insight');if(ins)ins.querySelector('h3').textContent=a.recommendation; if(ins)ins.querySelector('p').textContent=`Detected ${a.transactionCount} rows from your supplied data.`}
function renderCategories(items,c){if(!c)return;if(!items?.length){c.innerHTML='<div class="loading">No data yet.</div>';return}const max=items[0].amount||1;c.innerHTML=items.map(x=>`<div class="category-row"><div class="category-name">${esc(x.category)}</div><div class="progress"><div class="progress-fill" style="width:${Math.round(x.amount/max*100)}%"></div></div><div class="category-amount">${money(x.amount)}</div></div>`).join('')}
function renderChart(items,c){if(!c)return;if(!items?.length){c.innerHTML='<div class="loading">Add dated transactions to see trends.</div>';return}const max=Math.max(...items.map(x=>x.expenses),1);c.innerHTML=items.map(x=>`<div class="chart-column"><div class="chart-bar" style="height:${Math.max(8,x.expenses/max*82)}%"></div><div class="chart-value">${money(x.expenses)}</div><div class="chart-label">${esc(x.month)}</div></div>`).join('')}
function renderTransactions(items,c){if(!c)return;const rows=items||[];if(c.tagName==='TBODY'){c.innerHTML=rows.length?rows.map(t=>`<tr><td>${esc(t.date||'—')}</td><td>${esc(t.merchant)}</td><td>${esc(t.category)}</td><td class="${t.amount<0?'negative':'positive'}">${t.amount<0?'-':'+'}${money(Math.abs(t.amount))}</td><td><span class="mini-badge">Detected</span></td></tr>`).join(''):'<tr><td colspan="5">No transactions yet.</td></tr>';return}c.innerHTML=rows.length?rows.map(t=>`<div class="transaction"><div class="transaction-icon">${t.amount<0?'↘':'↗'}</div><div class="transaction-info"><div class="transaction-name">${esc(t.merchant)}</div><div class="transaction-date">${esc(t.date||'Date not provided')} · ${esc(t.category)}</div></div><div class="transaction-amount ${t.amount<0?'negative':'positive'}">${t.amount<0?'-':'+'}${money(Math.abs(t.amount))}</div></div>`).join(''):'<div class="loading">No transactions yet.</div>'}
function renderAnalytics(a){if(!a)return;setText('analytics-income',money(a.totalIncome));setText('analytics-expenses',money(a.totalExpenses));setText('analytics-savings',money(a.netSavings));setText('analytics-rate',a.savingsRate+'%');renderCategories(a.categories,$('analytics-categories'));renderChart(a.monthly,$('analytics-chart'));const tm=$('top-merchants');if(tm)tm.innerHTML=(a.topMerchants||[]).map(x=>`<div class="transaction"><div class="transaction-info"><div class="transaction-name">${esc(x.merchant)}</div></div><div class="transaction-amount negative">${money(x.amount)}</div></div>`).join('')||'<div class="loading">No merchant data.</div>';const rc=$('recurring-list');if(rc)rc.innerHTML='<div class="loading">Recurring patterns are inferred from repeated descriptions when enough history exists.</div>'}
async function loadState(){try{const j=await api('/api/state');state={hasData:j.hasData,analytics:j.analytics?.transactionCount?j.analytics:null};if(j.hasData){renderDashboard(j.analytics);renderContext(j.context);renderAnalysis(j.analytics);renderTransactions(j.transactions||[],$('transaction-table-body'));}else renderDashboard(null)}catch(e){renderDashboard(null)}}
async function resetData(){try{await api('/api/reset',{method:'POST',body:'{}'});state={hasData:false,analytics:null};$('problem-input').value='';$('data-input').value='';$('data-file').value='';$('analysis-output').classList.add('hidden');$('upload-status').textContent='';renderContext();renderDashboard(null);showToast('Saarthi workspace reset.')}catch(e){showToast(e.message)}}
function setupChat(){
  const fileInput=$('chat-file');
  const attach=$('attach-chat-file');
  const status=$('chat-upload-status');
  const send=async()=>{
    const input=$('chat-input'),q=input?.value.trim();
    if(!q)return;
    const box=$('chat-messages');
    box.innerHTML+=`<div class="message user">${esc(q)}</div>`;
    input.value='';
    const typing=document.createElement('div');
    typing.className='message ai'; typing.textContent='Saarthi is thinking…'; box.appendChild(typing); box.scrollTop=box.scrollHeight;
    try{
      const j=await api('/api/chat',{method:'POST',body:JSON.stringify({message:q,language:currentLang()})});
      typing.textContent=j.reply||'I could not produce an answer.';
      if(j.analytics){state.analytics=j.analytics;state.hasData=true;renderDashboard(j.analytics);renderAnalysis(j.analytics);}
      if(j.needsData){status.textContent='Attach an Excel/CSV file above, or use My Data.';}
    }catch(e){typing.textContent=e.message;}
  };
  const uploadFromChat=async(file)=>{
    if(!file)return;
    status.textContent=`Reading ${file.name}…`;
    attach.disabled=true;
    try{
      const fd=new FormData(); fd.append('file',file); fd.append('problem','');
      const j=await api('/api/import',{method:'POST',body:fd});
      state={hasData:true,analytics:j.analytics};
      renderDashboard(j.analytics); renderAnalysis(j.analytics); renderContext(j.context);
      status.textContent=`✓ ${j.context.detected} transaction rows loaded from ${file.name}`;
      const box=$('chat-messages');
      box.innerHTML+=`<div class="message ai">I’ve loaded <b>${esc(file.name)}</b> and understood ${j.context.detected} transaction rows. What would you like me to investigate?</div>`;
      box.scrollTop=box.scrollHeight;
    }catch(e){status.textContent=e.message;}
    finally{attach.disabled=false;fileInput.value='';}
  };
  attach?.addEventListener('click',()=>fileInput?.click());
  fileInput?.addEventListener('change',()=>uploadFromChat(fileInput.files?.[0]));
  $('send-message')?.addEventListener('click',send);
  $('chat-input')?.addEventListener('keydown',e=>{if(e.key==='Enter')send()});
  document.querySelectorAll('.prompt').forEach(p=>p.addEventListener('click',()=>{
    $('chat-input').value=p.textContent;
    send();
  }));
}

async function loadBanks(){try{const j=await api('/api/banks');const c=$('bank-list');if(c)c.innerHTML=j.map(b=>`<article class="panel bank-card"><div class="bank-logo">${esc(b.shortName)}</div><div class="bank-info"><strong>${esc(b.name)}</strong><span>Demo connection only</span></div><button class="connect-btn" data-bank="${esc(b.name)}">Use demo</button></article>`).join('')}catch(e){}}
document.addEventListener('DOMContentLoaded',()=>{setupAuth();setupNav();setupWorkspace();setupChat();loadState();loadBanks();document.querySelectorAll('.prompt').forEach(p=>p.dataset.default='yes')});

// v5 intelligence menu: every job can be entered through Data or AI mode.
function featureCopy(feature){
  return ({
    overview:['Financial Intelligence','Complete picture of income, expenses, savings and patterns.'],
    audit:['Audit Intelligence','Find duplicates, anomalies, recurring payments and rows that need review.'],
    compare:['Past Month Comparison','See what changed and identify the biggest drivers behind it.'],
    reconcile:['Missing Hisab','Look for incomplete periods, uncategorized entries and places where the supplied books do not explain themselves.'],
    goal:['Goal Planner','Turn a target and deadline into a measurable monthly plan.'],
    afford:['Affordability Check','Test a purchase against your detected surplus and target savings.'],
    decision:['Decision Lab','Simulate changes before making a financial decision.'],
    brief:['Financial Brief','A professional first-pass summary for the user, business owner or CA to review.'],
    data:['My Financial Data','Update the financial context Saarthi uses.'],
    ask:['Ask Saarthi AI','Ask a question in plain language.']
  }[feature]||['Financial Intelligence','Saarthi reasons from your supplied financial context.']);
}
function renderFeature(feature){
  const out=$('analysis-output'); if(!out) return;
  const a=state.analytics;
  if(!a){ out.classList.remove('hidden'); out.innerHTML='<article class="panel"><div class="empty-state"><div>📊</div><strong>Give Saarthi some data first.</strong><p>Upload an Excel/CSV or use AI mode to describe what you want to investigate.</p><button class="btn btn-dark" data-go="workspace" data-feature="data">Add financial data →</button></div></article>'; return; }
  out.classList.remove('hidden');
  const audit=a.audit||{};
  const months=a.monthly||[];
  const latest=months.at(-1), previous=months.at(-2);
  const pct=(x,y)=>y?(((x-y)/Math.abs(y))*100).toFixed(1):'—';
  const compareRows = latest&&previous ? [
    ['Income',previous.income,latest.income],['Expenses',previous.expenses,latest.expenses],['Net savings',previous.savings,latest.savings]
  ] : [];
  const gapMonths=months.length?months.filter((m,i)=>i>0 && (()=>{const d1=new Date(months[i-1].month+'-01'),d2=new Date(m.month+'-01');return (d2-d1)>45*86400000;})()).length:0;
  const top=a.categories?.[0];
  let body='';
  if(feature==='investigate') body=`<div class="feature-insight"><b>Saarthi is investigating the supplied history</b><p>It checks cash flow, month-to-month changes, category spikes, duplicates, recurring patterns, concentration and data-quality limitations.</p><button class="btn btn-dark" id="run-investigation">Investigate now →</button></div><div id="investigation-result" class="audit-list"></div>`;
  else if(feature==='overview') body=`<div class="analysis-grid"><div class="analysis-stat"><span>INCOME</span><strong>${money(a.totalIncome)}</strong></div><div class="analysis-stat"><span>EXPENSES</span><strong>${money(a.totalExpenses)}</strong></div><div class="analysis-stat"><span>SURPLUS</span><strong>${money(a.netSavings)}</strong></div><div class="analysis-stat"><span>SAVINGS RATE</span><strong>${a.savingsRate}%</strong></div></div><div class="feature-insight"><b>What Saarthi sees</b><p>${top?`${esc(top.category)} is your largest detected expense at ${money(top.amount)}.`:'There is not enough categorized expense data yet.'} ${a.periods>1?`You have ${a.periods} dated periods to compare.`:''}</p></div>`;
  else if(feature==='audit') body=`<div class="audit-strip"><div><b>${audit.reviewCount||0}</b><span>items to review</span></div><div><b>${audit.duplicates||0}</b><span>possible duplicates</span></div><div><b>${audit.anomalies||0}</b><span>unusual expenses</span></div><div><b>${audit.recurring?.length||0}</b><span>recurring patterns</span></div><div><b>${audit.uncategorized||0}</b><span>uncategorized</span></div></div><div class="audit-list">${(audit.issues||[]).map(i=>`<div class="audit-item ${esc(i.severity)}"><div><strong>${esc(i.title)}</strong><p>${esc(i.text)}</p></div><span>${i.confidence||0}%</span></div>`).join('')||'<div class="empty-state compact"><strong>No obvious flags.</strong><p>Saarthi did not find clear issues in the supplied rows.</p></div>'}</div>`;
  else if(feature==='compare') body=compareRows.length?`<div class="compare-head"><span>Previous</span><span>Latest</span><span>Change</span></div>${compareRows.map(r=>`<div class="compare-row"><strong>${esc(r[0])}</strong><span>${money(r[1])}</span><span>${money(r[2])}</span><b>${pct(r[2],r[1])}%</b></div>`).join('')}<div class="feature-insight"><b>Why it matters</b><p>${latest.savings<previous.savings?`Net savings fell by ${money(previous.savings-latest.savings)} in ${esc(latest.month)}.`:`Net savings improved by ${money(latest.savings-previous.savings)} in ${esc(latest.month)}.`}</p></div>`:'<div class="empty-state"><strong>Need at least two dated periods.</strong><p>Upload more months to unlock a real comparison.</p></div>';
  else if(feature==='reconcile') body=`<div class="audit-strip"><div><b>${a.periods}</b><span>dated periods</span></div><div><b>${gapMonths}</b><span>possible month gaps</span></div><div><b>${audit.uncategorized||0}</b><span>rows needing review</span></div><div><b>${audit.duplicates||0}</b><span>possible duplicates</span></div></div><div class="feature-insight"><b>Reconciliation principle</b><p>Saarthi only flags what can be supported by the supplied data. It will not invent a missing transaction. ${gapMonths?`There ${gapMonths===1?'is':'are'} ${gapMonths} possible gap${gapMonths===1?'':'s'} in the dated history.`:'No obvious month gap was detected.'}</p></div><div class="audit-list">${(audit.issues||[]).filter(i=>i.type==='data_quality'||i.type==='duplicate').slice(0,8).map(i=>`<div class="audit-item ${esc(i.severity)}"><div><strong>${esc(i.title)}</strong><p>${esc(i.text)}</p></div><span>${i.confidence||0}%</span></div>`).join('')||'<div class="empty-state compact"><strong>No obvious reconciliation flags.</strong><p>Human review is still recommended for source documents and closing balances.</p></div>'}</div>`;
  else if(feature==='goal') body=`<div class="goal-box"><label>Describe your goal<input id="feature-goal-input" placeholder="I need ₹50,000 in 5 months"></label><button class="btn btn-dark" id="feature-goal-run">Calculate plan →</button></div><div id="feature-goal-result" class="feature-insight"><b>Current detected surplus: ${money(a.netSavings)}</b><p>Enter a target and deadline to calculate the monthly requirement and gap.</p></div>`;
  else if(feature==='afford') body=`<div class="goal-box"><label>Purchase amount<input id="afford-amount" type="number" placeholder="30000"></label><button class="btn btn-dark" id="afford-run">Check →</button></div><div id="afford-result" class="feature-insight"><b>Detected surplus: ${money(a.netSavings)}</b><p>Saarthi will compare the purchase with your detected surplus. This is a planning signal, not a financial guarantee.</p></div>`;
  else if(feature==='decision') body=`<div class="goal-box"><label>Scenario<input id="decision-input" placeholder="What if my income falls 10%?"></label><button class="btn btn-dark" id="decision-run">Simulate →</button></div><div id="decision-result" class="feature-insight"><b>Decision Lab</b><p>Try: “income falls 10%”, “expenses rise 15%”, or “cut Shopping by 20%”.</p></div>`;
  else if(feature==='brief') body=`<div class="brief-grid"><div><span>DATASET</span><strong>${a.transactionCount} rows</strong></div><div><span>PERIODS</span><strong>${a.periods}</strong></div><div><span>REVIEW ITEMS</span><strong>${audit.reviewCount||0}</strong></div><div><span>DATA COVERAGE</span><strong>${audit.coverage||'Limited'}</strong></div></div><div class="feature-insight"><b>Executive summary</b><p>${esc(a.recommendation)}</p></div><div class="feature-insight"><b>Professional review note</b><p>Saarthi is a first-pass intelligence layer. Source documents, tax treatment, accounting standards and material judgments should be reviewed by a qualified professional.</p></div><button class="btn btn-dark" id="print-brief">Print / Save this brief →</button>`;
  else body=`<div class="feature-insight"><b>Ask Saarthi anything</b><p>Use the AI mode or open the conversation to ask questions against this same financial context.</p><button class="btn btn-dark" data-go="chat">Open Ask Saarthi →</button></div>`;
  const [title,sub]=featureCopy(feature);
  out.innerHTML=`<article class="panel"><div class="analysis-head"><div><span class="section-kicker">${feature==='brief'?'CA / BUSINESS READY':'SAARTHI INTELLIGENCE'}</span><h3>${title}</h3><p class="workspace-panel-note">${sub}</p></div><span class="mini-badge">${a.transactionCount} rows understood</span></div>${body}</article>`;
  bindFeatureActions(feature,a);
}
function bindFeatureActions(feature,a){
  $('run-investigation')?.addEventListener('click',async()=>{const out=$('investigation-result');out.innerHTML='<div class="feature-insight"><b>Investigating…</b><p>Checking the strongest signals in your supplied data.</p></div>';try{const r=await api('/api/investigate',{method:'POST',body:JSON.stringify({})});out.innerHTML=(r.findings||[]).map(f=>`<div class="audit-item ${f.priority===1?'high':f.priority===2?'medium':'low'}"><div><strong>${esc(f.title)}</strong><p>${esc(f.evidence)}</p></div><span>${f.confidence}%</span></div>`).join('')||'<div class="empty-state compact"><strong>No strong findings yet.</strong><p>Upload a longer history if you want deeper investigation.</p></div>';if(r.actions?.length)out.innerHTML+=`<div class="feature-insight"><b>Suggested next checks</b><p>${r.actions.map(esc).join('<br>')}</p></div>`;}catch(e){out.innerHTML=`<div class="feature-insight"><b>Investigation unavailable</b><p>${esc(e.message)}</p></div>`;}});
  $('feature-goal-run')?.addEventListener('click',()=>{const p=$('feature-goal-input').value; const nums=[...p.matchAll(/₹?\s*([\d,]+)/g)].map(x=>Number(x[1].replace(/,/g,''))); const target=nums[0]||0; const hm=p.match(/(\d+)\s*months?/i); const h=hm?Number(hm[1]):0; const req=h?target/h:target; const gap=Math.max(0,req-a.netSavings); $('feature-goal-result').innerHTML=`<b>Required: ${money(req)} per month</b><p>Your detected surplus is ${money(a.netSavings)}. ${gap?`You need about ${money(gap)} more per period.`:'This target fits within your detected surplus.'}</p>`});
  $('afford-run')?.addEventListener('click',()=>{const amt=Number($('afford-amount').value||0);const remaining=a.netSavings-amt; $('afford-result').innerHTML=`<b>${remaining>=0?'Potentially affordable':'Not supported by current surplus'}</b><p>Purchase: ${money(amt)} · Detected surplus: ${money(a.netSavings)} · After purchase: ${money(remaining)}. Saarthi has not assumed an opening balance or future income.</p>`});
  $('decision-run')?.addEventListener('click',async()=>{const q=$('decision-input').value.trim();const out=$('decision-result');if(!q)return;out.innerHTML='<b>Running Digital Twin…</b><p>Testing the scenario without changing your real data.</p>';try{const r=await api('/api/decision',{method:'POST',body:JSON.stringify({scenario:q})});const d=r.delta||{};out.innerHTML=`<b>Scenario result</b><p>Surplus moves from <strong>${money(r.baseline.surplus)}</strong> to <strong>${money(r.final.surplus)}</strong> (${d.surplus>=0?'+':''}${money(d.surplus)}). Savings rate changes from ${r.baseline.savingsRate}% to ${r.final.savingsRate}%. This simulation does not modify your real ledger.</p>`;}catch(e){out.innerHTML=`<b>Scenario unavailable</b><p>${esc(e.message)}</p>`;}});
  $('print-brief')?.addEventListener('click',()=>window.print());
}
function setupV5Menu(){
  document.addEventListener('click',e=>{
    const f=e.target.closest('[data-feature]'); if(f){e.preventDefault(); const feature=f.dataset.feature; if(feature==='data'){showSection('workspace'); return;} showSection('workspace'); renderFeature(feature); document.querySelectorAll('.feature-card').forEach(x=>x.classList.toggle('selected',x.dataset.feature===feature)); return;}
    const mode=e.target.closest('.mode-btn'); if(mode){document.querySelectorAll('.mode-btn').forEach(x=>x.classList.remove('active'));mode.classList.add('active');$('data-mode-panel')?.classList.toggle('hidden',mode.dataset.mode!=='data');$('ai-mode-panel')?.classList.toggle('hidden',mode.dataset.mode!=='ai');}
    const ai=e.target.closest('[data-ai-prompt]'); if(ai){$('chat-input').value=ai.dataset.aiPrompt;showSection('chat');$('send-message')?.click();}
  });
  document.querySelectorAll('.quick-ai-grid button').forEach(b=>b.addEventListener('click',()=>{}));
}
function refreshHomeDataStatus(){const s=$('home-data-status'),d=$('home-data-detail');if(!s||!d)return;if(state.hasData){s.textContent='Financial context ready';d.textContent=`${state.analytics.transactionCount} rows · ${state.analytics.periods} dated periods · Income ${money(state.analytics.totalIncome)} · Expenses ${money(state.analytics.totalExpenses)}`;}else{s.textContent='No financial data loaded';d.textContent='Upload Excel/CSV once. Saarthi will use it across every feature.';}}
document.addEventListener('DOMContentLoaded',()=>{setupV5Menu();refreshHomeDataStatus();});
const _oldLoadState=loadState;
loadState=async function(){await _oldLoadState();refreshHomeDataStatus();};

/* ===================== SAARTHI v6 ===================== */
const V6_FEATURE_COPY={
 overview:['Understand My Finances','Turn your supplied data into a clear financial story.'],
 investigate:['Investigate My Finances','Saarthi automatically ranks the strongest evidence-supported findings in your financial history.'],
 audit:['Audit My Data','A first-pass audit for duplicates, anomalies, recurring patterns and review points.'],
 compare:['Compare Past Months','See what changed, measure the difference and understand the drivers.'],
 reconcile:['Find Missing Hisab','Find supported gaps and reconciliation clues without inventing transactions.'],
 goal:['Plan a Goal','Translate a target and deadline into a measurable savings requirement.'],
 afford:['Can I Afford This?','Test a purchase against the surplus Saarthi actually detected.'],
 decision:['Decision Lab','Stress-test income, spending and business scenarios before deciding.'],
 brief:['Financial Brief','Create a concise, professional first-pass financial intelligence brief.'],
 ask:['Ask Saarthi AI','Ask a natural-language question using the same financial context.'],
 kyc:['Bank Forms & KYC','Simplify long forms, KYC instructions and banking procedures into guided steps.']
};
const LANG={
 en:{welcome:'Your money, understood.',sub:'Sign in to continue to your personal financial intelligence workspace.',figure:'What do you want to figure out?',menuSub:'Choose a job. Saarthi will use the financial context you provide and build the analysis around your question.',ask:'Ask Saarthi AI',kyc:'Bank Forms & KYC'},
 hi:{welcome:'आपका पैसा, अब आसान भाषा में।',sub:'अपने वित्तीय इंटेलिजेंस वर्कस्पेस में आगे बढ़ने के लिए साइन इन करें।',figure:'आप क्या समझना चाहते हैं?',menuSub:'एक काम चुनें। Saarthi आपके दिए हुए वित्तीय डेटा से उसी सवाल के अनुसार विश्लेषण बनाएगा।',ask:'Saarthi AI से पूछें',kyc:'बैंक फॉर्म और KYC'},
 gu:{welcome:'તમારા પૈસાની સમજ, સરળ ભાષામાં.',sub:'તમારા નાણાકીય ઇન્ટેલિજન્સ વર્કસ્પેસમાં આગળ વધવા માટે સાઇન ઇન કરો.',figure:'તમારે શું સમજવું છે?',menuSub:'એક કામ પસંદ કરો. Saarthi તમારા આપેલા નાણાકીય ડેટા પરથી તમારા પ્રશ્ન મુજબ વિશ્લેષણ બનાવશે.',ask:'Saarthi AI ને પૂછો',kyc:'બેંક ફોર્મ અને KYC'}
};
function currentLang(){return localStorage.getItem('saarthi_language')||'en'}
function applyLanguage(lang){lang=LANG[lang]?lang:'en';localStorage.setItem('saarthi_language',lang);document.documentElement.lang=lang;['language-select','auth-language'].forEach(id=>{const e=$(id);if(e)e.value=lang});const l=LANG[lang];setText('auth-title',l.welcome);setText('auth-subtitle',l.sub);setText('email-label',lang==='en'?'Email address':lang==='hi'?'ईमेल पता':'ઈમેલ');setText('password-label',lang==='en'?'Password':lang==='hi'?'पासवर्ड':'પાસવર્ડ');setText('login-btn',lang==='en'?'Sign in securely →':lang==='hi'?'सुरक्षित साइन इन →':'સુરક્ષિત સાઇન ઇન →');const h=document.querySelector('.menu-intro h2'),p=document.querySelector('.menu-intro p');if(h)h.textContent=l.figure;if(p)p.textContent=l.menuSub;document.querySelectorAll('.feature-card').forEach(c=>{const f=c.dataset.feature;if(f==='ask')c.querySelector('strong').textContent=l.ask;if(f==='kyc')c.querySelector('strong').textContent=l.kyc});}
function aiWidget(feature){return `<div class="feature-ai-head"><div><span class="section-kicker">AI COPILOT</span><h4>Ask Saarthi about ${esc(V6_FEATURE_COPY[feature]?.[0]||'this task')}</h4><div class="language-note">Answers use your current financial context. Language: ${currentLang()==='hi'?'हिन्दी':currentLang()==='gu'?'ગુજરાતી':'English'}.</div></div><span class="mini-badge">AI + calculations</span></div><div class="feature-ai-input"><input id="feature-ai-input" placeholder="Ask a question about this feature…"><button class="btn btn-dark" id="feature-ai-send">Ask AI →</button></div><div id="feature-ai-reply" class="feature-ai-reply">Saarthi will explain the result and show what to review next.</div>`}
async function askFeatureAI(feature){const input=$('feature-ai-input'),reply=$('feature-ai-reply');if(!input||!reply)return;const q=input.value.trim();if(!q)return;reply.textContent='Saarthi is thinking…';try{const j=await api('/api/chat',{method:'POST',body:JSON.stringify({message:`Feature: ${V6_FEATURE_COPY[feature]?.[0]||feature}. ${q}`,language:currentLang()})});reply.textContent=j.reply||'I could not generate a response.'}catch(e){reply.textContent=e.message}}
function addFeatureAI(feature){const card=document.getElementById('feature-ai-card');if(!card)return;card.innerHTML=aiWidget(feature);$('feature-ai-send')?.addEventListener('click',()=>askFeatureAI(feature));$('feature-ai-input')?.addEventListener('keydown',e=>{if(e.key==='Enter')askFeatureAI(feature)});}
function simplifyKYC(){const raw=$('kyc-form-text')?.value.trim();const result=$('kyc-result');if(!result)return;const task=raw||'Complete a bank KYC update';const hasAddress=/address|residen|current address/i.test(task),hasId=/id|identity|pan|aadhaar|passport|kyc/i.test(task),hasIncome=/income|salary|occupation|employer/i.test(task);const steps=['Read the bank requirement and identify exactly what is being requested.',hasId?'Keep the required identity information/documents ready according to the bank instructions.':'Confirm which identity/KYC information the bank requires.',hasAddress?'Confirm your address details and the bank’s accepted proof.':'Check whether address proof is required for this procedure.',hasIncome?'Keep occupation/income information ready if the form asks for it.':'Check whether occupation or income fields apply.', 'Review every field, verify spelling/numbers, then submit through the bank’s official channel.'];result.innerHTML=`<div class="feature-insight"><b>Saarthi simplified this procedure</b><p>${esc(task.slice(0,500))}</p></div>${steps.map((x,i)=>`<div class="kyc-step"><b>${i+1}</b><div><strong>Step ${i+1}</strong><p>${esc(x)}</p></div></div>`) .join('')}<div class="feature-insight"><b>What Saarthi will not do</b><p>It will not ask for or store bank passwords, OTPs, card PINs, CVV, or government ID numbers. It also cannot make the bank’s final KYC decision.</p></div>`}
function setupKYC(){document.querySelectorAll('.kyc-task').forEach(b=>b.addEventListener('click',()=>{$('kyc-form-text').value=b.dataset.kycTask;simplifyKYC()}));$('kyc-simplify')?.addEventListener('click',simplifyKYC);$('kyc-reset')?.addEventListener('click',()=>{$('kyc-form-text').value='';$('kyc-result').innerHTML='<div class="empty-state compact"><strong>Nothing to decode yet.</strong><p>Paste instructions or choose a common task.</p></div>'});addFeatureAI('kyc')}
function renderFeature(feature){const out=$('analysis-output');if(!out)return;if(!state.analytics){out.classList.remove('hidden');out.innerHTML='<article class="panel"><div class="empty-state"><strong>Load financial data first.</strong><p>Upload Excel/CSV or load the example dataset. Saarthi needs actual supplied data for financial calculations.</p></div></article>';return}out.classList.remove('hidden');const a=state.analytics,audit=a.audit||{},months=a.monthly||[],latest=months.at(-1),previous=months.at(-2),top=a.categories?.[0];let body='';if(feature==='kyc'){showSection('kyc');return;}if(feature==='overview')body=`<div class="analysis-grid"><div class="analysis-stat"><span>INCOME</span><strong>${money(a.totalIncome)}</strong></div><div class="analysis-stat"><span>EXPENSES</span><strong>${money(a.totalExpenses)}</strong></div><div class="analysis-stat"><span>SURPLUS</span><strong>${money(a.netSavings)}</strong></div><div class="analysis-stat"><span>SAVINGS RATE</span><strong>${a.savingsRate}%</strong></div></div><div class="feature-insight"><b>What Saarthi sees</b><p>${top?`${esc(top.category)} is your largest detected expense at ${money(top.amount)}.`:'There is not enough categorized expense data yet.'} ${a.periods>1?`You have ${a.periods} dated periods to compare.`:''}</p></div>`;else if(feature==='audit')body=`<div class="audit-strip"><div><b>${audit.reviewCount||0}</b><span>items to review</span></div><div><b>${audit.duplicates||0}</b><span>possible duplicates</span></div><div><b>${audit.anomalies||0}</b><span>unusual expenses</span></div><div><b>${audit.recurring?.length||0}</b><span>recurring patterns</span></div><div><b>${audit.uncategorized||0}</b><span>uncategorized</span></div></div><div class="audit-list">${(audit.issues||[]).map(i=>`<div class="audit-item ${esc(i.severity)}"><div><strong>${esc(i.title)}</strong><p>${esc(i.text)}</p></div><span>${i.confidence||0}%</span></div>`).join('')||'<div class="empty-state compact"><strong>No obvious flags.</strong><p>Saarthi did not find clear issues in the supplied rows.</p></div>'}</div>`;else if(feature==='compare')body=latest&&previous?`<div class="compare-head"><span>Previous</span><span>Latest</span><span>Change</span></div>${[['Income',previous.income,latest.income],['Expenses',previous.expenses,latest.expenses],['Net savings',previous.savings,latest.savings]].map(r=>`<div class="compare-row"><strong>${r[0]}</strong><span>${money(r[1])}</span><span>${money(r[2])}</span><b>${r[1]?(((r[2]-r[1])/Math.abs(r[1]))*100).toFixed(1):'—'}%</b></div>`).join('')}<div class="feature-insight"><b>Why it matters</b><p>${latest.savings<previous.savings?`Net savings fell by ${money(previous.savings-latest.savings)}.`:`Net savings improved by ${money(latest.savings-previous.savings)}.`}</p></div>`:'<div class="empty-state"><strong>Need at least two dated periods.</strong><p>Upload more months to unlock a real comparison.</p></div>';else if(feature==='reconcile')body=`<div class="audit-strip"><div><b>${a.periods}</b><span>dated periods</span></div><div><b>${audit.uncategorized||0}</b><span>rows needing review</span></div><div><b>${audit.duplicates||0}</b><span>possible duplicates</span></div></div><div class="feature-insight"><b>Missing hisab principle</b><p>Saarthi only flags evidence-supported gaps. It will never invent a transaction. Review source statements and opening/closing balances with a qualified professional.</p></div>`;else if(feature==='goal')body=`<div class="goal-box"><label>Describe your goal<input id="feature-goal-input" placeholder="I need ₹50,000 in 5 months"></label><button class="btn btn-dark" id="feature-goal-run">Calculate plan →</button></div><div id="feature-goal-result" class="feature-insight"><b>Current detected surplus: ${money(a.netSavings)}</b><p>Enter a target and deadline.</p></div>`;else if(feature==='afford')body=`<div class="goal-box"><label>Purchase amount<input id="afford-amount" type="number" placeholder="30000"></label><button class="btn btn-dark" id="afford-run">Check →</button></div><div id="afford-result" class="feature-insight"><b>Detected surplus: ${money(a.netSavings)}</b><p>This is a planning signal, not a guarantee.</p></div>`;else if(feature==='decision')body=`<div class="goal-box"><label>Scenario<input id="decision-input" placeholder="What if my salary falls 10%?"></label><button class="btn btn-dark" id="decision-run">Simulate →</button></div><div id="decision-result" class="feature-insight"><b>Decision Lab</b><p>Try income falls 10%, expenses rise 15%, or Shopping falls 20%.</p></div>`;else if(feature==='brief')body=`<div class="brief-grid"><div><span>DATASET</span><strong>${a.transactionCount} rows</strong></div><div><span>PERIODS</span><strong>${a.periods}</strong></div><div><span>REVIEW ITEMS</span><strong>${audit.reviewCount||0}</strong></div><div><span>DATA COVERAGE</span><strong>${audit.coverage||'Limited'}</strong></div></div><div class="feature-insight"><b>Executive summary</b><p>${esc(a.recommendation)}</p></div><div class="feature-insight"><b>Professional review note</b><p>Saarthi is a first-pass intelligence layer. Source documents, tax treatment, accounting standards and material judgments should be reviewed by a qualified professional.</p></div><button class="btn btn-dark" id="print-brief">Print / Save this brief →</button>`;else body=`<div class="feature-insight"><b>Ask Saarthi anything</b><p>Ask naturally. Saarthi reasons from the same financial context instead of making you re-enter it.</p><button class="btn btn-dark" data-go="chat">Open full conversation →</button></div>`;const [title,sub]=V6_FEATURE_COPY[feature]||V6_FEATURE_COPY.overview;out.innerHTML=`<article class="panel"><div class="analysis-head"><div><span class="section-kicker">SAARTHI INTELLIGENCE</span><h3>${title}</h3><p class="workspace-panel-note">${sub}</p></div><span class="mini-badge">${a.transactionCount} rows understood</span></div>${body}</article><div class="feature-ai-card" id="feature-ai-card">${aiWidget(feature)}</div>`;bindFeatureActions(feature,a);$('feature-ai-send')?.addEventListener('click',()=>askFeatureAI(feature));$('feature-ai-input')?.addEventListener('keydown',e=>{if(e.key==='Enter')askFeatureAI(feature)});}
function setupV6(){applyLanguage(currentLang());$('language-select')?.addEventListener('change',e=>applyLanguage(e.target.value));$('auth-language')?.addEventListener('change',e=>applyLanguage(e.target.value));setupKYC();}
window.addEventListener('DOMContentLoaded',setupV6);

/* ===================== SAARTHI Batch 3 + 4 ===================== */
function injectBatch34UI(){
  if(document.getElementById('saarthi-b34')) return;
  const nav=document.querySelector('.nav');
  if(nav){
    const b=document.createElement('button'); b.className='nav-item'; b.dataset.section='intel'; b.innerHTML='<span>◎</span>Research & Brief'; nav.appendChild(b);
  }
  const main=document.querySelector('.content'); if(!main)return;
  const sec=document.createElement('section'); sec.className='section'; sec.id='intel-section'; sec.innerHTML=`
    <div id="saarthi-b34" class="section-intro workspace-top"><div><span class="section-kicker">SAARTHI INTELLIGENCE LAYER</span><h2>Research. Verify. Brief.</h2><p>Use current public information alongside your financial context, then turn the result into an evidence-led brief.</p></div><span class="mini-badge">Batch 3 + 4</span></div>
    <div class="b34-grid">
      <article class="panel">
        <div class="panel-head"><div><span class="section-kicker">WEB INTELLIGENCE</span><h3>Research a current question</h3></div><span class="mini-badge">Live sources</span></div>
        <div class="b34-search"><input id="web-research-input" placeholder="e.g. scholarships available in Gujarat for students in 2026"><button class="btn btn-dark" id="web-research-run">Research →</button></div>
        <div class="b34-suggestions"><button data-research="Find current government schemes in India relevant to saving money">Government schemes</button><button data-research="Find current student scholarships in Gujarat and their official eligibility requirements">Scholarships</button><button data-research="Find the current official fees and charges for a bank account in India">Bank fees</button></div>
        <div id="web-research-result" class="b34-result"><div class="empty-state compact"><strong>Nothing researched yet.</strong><p>Saarthi will use current public sources when AI web research is configured.</p></div></div>
      </article>
      <article class="panel">
        <div class="panel-head"><div><span class="section-kicker">FINANCIAL BRIEF</span><h3>Your Control Room</h3></div><button class="btn btn-ghost-dark" id="refresh-brief">Refresh</button></div>
        <div id="control-room" class="control-room"><div class="empty-state compact"><strong>Load financial data first.</strong><p>Your real findings, trends and review items will appear here.</p></div></div>
      </article>
    </div>`;
  main.appendChild(sec);
  document.querySelectorAll('.b34-suggestions button').forEach(b=>b.addEventListener('click',()=>{ $('web-research-input').value=b.dataset.research; runWebResearch(); }));
  $('web-research-run')?.addEventListener('click',runWebResearch); $('web-research-input')?.addEventListener('keydown',e=>{if(e.key==='Enter')runWebResearch()}); $('refresh-brief')?.addEventListener('click',loadControlRoom);
  loadControlRoom();
}
async function runWebResearch(){const input=$('web-research-input'),out=$('web-research-result');if(!input||!out)return;const q=input.value.trim();if(!q)return;out.innerHTML='<div class="feature-insight"><b>Researching current sources…</b><p>Saarthi is checking public information and separating facts from interpretation.</p></div>';try{const r=await api('/api/research',{method:'POST',body:JSON.stringify({query:q})});out.innerHTML=`<div class="feature-insight"><b>Research result</b><p>${esc(r.answer).replace(/\n/g,'<br>')}</p></div><div class="workspace-panel-note">Verify important eligibility, fees and deadlines against the linked official source before acting.</div>`;}catch(e){out.innerHTML=`<div class="feature-insight"><b>Research unavailable</b><p>${esc(e.message)}</p></div>`;}}
async function loadControlRoom(){const out=$('control-room');if(!out)return;if(!state.hasData){out.innerHTML='<div class="empty-state compact"><strong>Load financial data first.</strong><p>Upload Excel/CSV from Ask Saarthi or My Data.</p></div>';return;}out.innerHTML='<div class="feature-insight"><b>Building brief…</b><p>Ranking the strongest evidence from your current dataset.</p></div>';try{const r=await api('/api/brief');const s=r.snapshot||{};out.innerHTML=`<div class="control-stats"><div><span>TRANSACTIONS</span><b>${s.transactions}</b></div><div><span>PERIODS</span><b>${s.periods}</b></div><div><span>INCOME</span><b>${money(s.income)}</b></div><div><span>EXPENSES</span><b>${money(s.expenses)}</b></div><div><span>SURPLUS</span><b>${money(s.surplus)}</b></div><div><span>HEALTH SIGNAL</span><b>${s.healthScore}/100</b></div></div><div class="feature-insight"><b>Top findings</b><p>${(r.findings||[]).slice(0,5).map((f,i)=>`${i+1}. ${esc(f.title)} — ${esc(f.evidence)} (${f.confidence}%)`).join('<br>')||'No strong findings yet.'}</p></div><div class="feature-insight"><b>Next actions</b><p>${(r.actions||[]).map(esc).join('<br>')||'No immediate actions suggested.'}</p></div><button class="btn btn-dark" id="print-control-room">Print / Save brief →</button>`;$('print-control-room')?.addEventListener('click',()=>window.print());}catch(e){out.innerHTML=`<div class="feature-insight"><b>Brief unavailable</b><p>${esc(e.message)}</p></div>`;}}
const _oldShowSection=showSection;
showSection=function(name){_oldShowSection(name);if(name==='intel'){setText('page-title','Research & Brief');setText('page-subtitle','Current public information plus an evidence-led financial brief.');loadControlRoom();}};
window.addEventListener('DOMContentLoaded',injectBatch34UI);

/* ===================== SAARTHI FINAL SUBMISSION PACK ===================== */
(function finalSubmissionPack(){
  function addUI(){
    if(document.getElementById('final-pack')) return;
    const nav=document.querySelector('.nav');
    if(nav){ const b=document.createElement('button'); b.className='nav-item'; b.dataset.section='lab'; b.innerHTML='<span>◈</span>Voice & Safety Lab'; nav.appendChild(b); }
    const main=document.querySelector('.content'); if(!main)return;
    const sec=document.createElement('section'); sec.className='section'; sec.id='lab-section'; sec.innerHTML=`
      <div class="section-intro"><span class="section-kicker">SAARTHI NEXT GEN</span><h2>Talk. Decide. Stay safe.</h2><p>Voice conversation, decision simulations, scam-signal checks and personal workspace controls.</p></div>
      <div class="b34-grid">
        <article class="panel"><div class="panel-head"><div><span class="section-kicker">VOICE BOT</span><h3>Talk to Saarthi</h3></div><span class="mini-badge" id="voice-status">Ready</span></div>
          <div class="voice-visual"><div class="voice-orb" id="voice-orb">S</div><p id="voice-caption">Press the microphone and speak naturally.</p></div>
          <div class="b34-search"><input id="voice-text" placeholder="Or type what you want to ask…"><button class="btn btn-dark" id="voice-mic">🎙 Start</button><button class="btn btn-ghost-dark" id="voice-send">Ask →</button></div>
          <div class="feature-insight"><b>Voice privacy</b><p>Speech recognition uses your browser's available speech service. Saarthi does not need OTPs, PINs, CVVs or passwords.</p></div>
        </article>
        <article class="panel"><div class="panel-head"><div><span class="section-kicker">SAFETY CENTER</span><h3>Check a suspicious message</h3></div><span class="mini-badge">Signals ≠ proof</span></div>
          <textarea id="scam-text" class="problem-input" placeholder="Paste a message or offer you want Saarthi to review…"></textarea><button class="btn btn-dark" id="scam-check">Check signals →</button><div id="scam-result" class="b34-result"><div class="empty-state compact"><strong>No message checked.</strong><p>Saarthi will look for urgency, impersonation, payment pressure, OTP requests and suspicious links.</p></div></div>
        </article>
      </div>
      <div class="b34-grid">
        <article class="panel"><div class="panel-head"><div><span class="section-kicker">DECISION LAB</span><h3>Digital Twin scenarios</h3></div><span class="mini-badge">No real data changed</span></div>
          <div class="b34-search"><input id="twin-scenario" placeholder="e.g. salary falls 20% or shopping falls 30%"><button class="btn btn-dark" id="twin-run">Simulate →</button></div><div id="twin-result" class="b34-result"><div class="empty-state compact"><strong>Test a future.</strong><p>Scenarios are temporary calculations and never modify your uploaded transactions.</p></div></div>
        </article>
        <article class="panel"><div class="panel-head"><div><span class="section-kicker">MEMORY & PRIVACY</span><h3>Your Saarthi workspace</h3></div><span class="mini-badge">Local demo memory</span></div>
          <div id="memory-panel" class="feature-insight"></div><div class="workspace-actions"><button class="btn btn-dark" id="remember-language">Remember language</button><button class="btn btn-ghost-dark" id="clear-memory">Clear local preferences</button></div>
        </article>
      </div>`; main.appendChild(sec);
    setupVoice(); setupScam(); setupTwin(); setupMemory();
  }
  function setupVoice(){
    const mic=$('voice-mic'), input=$('voice-text'), status=$('voice-status'), cap=$('voice-caption'), orb=$('voice-orb');
    const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
    if(!SR){mic.disabled=true;status.textContent='Browser voice unavailable';return;}
    const rec=new SR(); rec.lang=currentLang()==='hi'?'hi-IN':currentLang()==='gu'?'gu-IN':'en-IN'; rec.interimResults=false; rec.maxAlternatives=1;
    rec.onstart=()=>{status.textContent='Listening…';orb.classList.add('voice-live');cap.textContent='I’m listening…';};
    rec.onresult=e=>{input.value=e.results[0][0].transcript;cap.textContent='Got it. Press Ask to send it.';};
    rec.onerror=()=>{status.textContent='Ready';cap.textContent='Voice input could not be started. You can type instead.';orb.classList.remove('voice-live');};
    rec.onend=()=>{status.textContent='Ready';orb.classList.remove('voice-live');};
    mic.onclick=()=>rec.start();
    $('voice-send').onclick=()=>{const q=input.value.trim();if(!q)return; $('chat-input').value=q; showSection('chat'); $('send-message')?.click();};
    const box=$('chat-messages'); if(box && 'speechSynthesis' in window){new MutationObserver(()=>{const ai=[...box.querySelectorAll('.message.ai')].at(-1); if(ai && ai.textContent && !/thinking|Hi!/.test(ai.textContent)){window.speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(ai.textContent.replace(/\s+/g,' ').trim()); u.lang=currentLang()==='hi'?'hi-IN':currentLang()==='gu'?'gu-IN':'en-IN'; window.speechSynthesis.speak(u);}}).observe(box,{childList:true,subtree:true,characterData:true});}
  }
  function setupScam(){ $('scam-check')?.addEventListener('click',()=>{const t=$('scam-text').value.trim();const out=$('scam-result');if(!t){out.innerHTML='<div class="feature-insight"><b>Add a message first.</b><p>Paste the text you want checked.</p></div>';return;} const rules=[['Urgency pressure',/urgent|immediately|act now|within \d+ (minutes?|hours?)/i],['OTP / credential request',/otp|one[- ]time password|pin|cvv|password|verification code/i],['Payment pressure',/pay|transfer|send money|fee|deposit|upi/i],['Impersonation signal',/bank|police|government|income tax|rbi|customer care|support/i],['Suspicious link',/https?:\/\/|bit\.ly|tinyurl|\.tk\b/i]]; const hits=rules.filter(x=>x[1].test(t)).map(x=>x[0]); const level=hits.length>=3?'High':hits.length===2?'Elevated':hits.length===1?'Review':'Low'; out.innerHTML=`<div class="feature-insight"><b>${level} signal level</b><p>${hits.length?hits.map(esc).join(' · '):'No common scam signals were detected by these simple checks.'}</p></div><div class="workspace-panel-note">These are indicators, not proof. Never share OTP, PIN, CVV or passwords.</div>`; }); }
  function setupTwin(){ $('twin-run')?.addEventListener('click',async()=>{const q=$('twin-scenario').value.trim(),out=$('twin-result');if(!q)return;if(!state.hasData){out.innerHTML='<div class="feature-insight"><b>Load financial data first.</b><p>The Digital Twin needs your supplied numbers.</p></div>';return;} out.innerHTML='<div class="feature-insight"><b>Running scenario…</b><p>Your original transactions remain unchanged.</p></div>';try{const r=await api('/api/chat',{method:'POST',body:JSON.stringify({message:`Decision Lab scenario: ${q}. Calculate the impact using my supplied financial data. Do not modify real data.`,language:currentLang()})});out.innerHTML=`<div class="feature-insight"><b>Scenario result</b><p>${esc(r.reply||'No result').replace(/\n/g,'<br>')}</p></div>`;}catch(e){out.innerHTML=`<div class="feature-insight"><b>Scenario unavailable</b><p>${esc(e.message)}</p></div>`;}}); }
  function setupMemory(){const p=$('memory-panel');if(!p)return;const lang=currentLang();p.innerHTML=`<b>Working preference</b><p>Language: ${lang==='hi'?'Hindi':lang==='gu'?'Gujarati':'English'}. Demo preferences are stored locally in this browser.</p>`;$('remember-language')?.addEventListener('click',()=>{localStorage.setItem('saarthi_preferred_language',currentLang());showToast('Language preference saved locally.');});$('clear-memory')?.addEventListener('click',()=>{localStorage.removeItem('saarthi_preferred_language');showToast('Local preference cleared.');setupMemory();});}
  const oldShow=window.showSection; if(oldShow) window.showSection=function(name){oldShow(name);if(name==='lab'){setText('page-title','Voice & Safety Lab');setText('page-subtitle','Talk to Saarthi, test decisions and check scam signals.');}};
  window.addEventListener('DOMContentLoaded',addUI);
})();

