function lang(){return localStorage.getItem('saarthi_language')||'en'}
function tx(){return T[lang()]||T.en}
function applyV7Language(){const l=tx();document.querySelectorAll('.nav-item').forEach((b,i)=>{if(l.nav[i]){const s=b.querySelector('span');b.innerHTML=(s?s.outerHTML:'')+l.nav[i]}});setText('auth-title',l.authTitle);setText('auth-subtitle',l.authSub);setText('login-btn',l.sign);setText('demo-login',l.demo);setText('page-title',l.dash);setText('page-subtitle',l.dashSub);const h=document.querySelector('.menu-intro h2'),p=document.querySelector('.menu-intro p');if(h)h.textContent=l.figure;if(p)p.textContent=l.menuSub;document.querySelectorAll('.quick-card p').forEach((e,i)=>{if(l.quick[i])e.textContent=l.quick[i]});document.querySelectorAll('[data-v7]').forEach(e=>{const k=e.dataset.v7;if(l[k])e.textContent=l[k]});const sel=$('v7-language');if(sel)sel.value=lang()}
